-- ----------------------------
-- Table structure for lcp_dynamic_form
-- ----------------------------
DROP TABLE IF EXISTS `lcp_dynamic_form`;
CREATE TABLE `lcp_dynamic_form`  (
  `id` bigint NOT NULL,
  `form_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '表单编码',
  `title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '表单名称/页面标题',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '表单说明',
  `process_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '关联流程编码',
  `style` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '扩展表单的CSS样式',
  `kendo_script` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '扩展表单的js脚本(kendoui版)',
  `vue_script` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '扩展表单的js脚本(vue版)',
  `status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '表单状态：0草稿/1已发布',
  `version` int NULL DEFAULT NULL COMMENT '版本号，同一表单依次递增',
  `enabled_flag` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'Y' COMMENT '是否启用（Y/N）',
  `is_delete` varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'N' COMMENT '逻辑删除字段',
  `created_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `created_by_user` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建用户',
  `creation_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `last_updated_by` bigint NULL DEFAULT NULL COMMENT '修改人',
  `last_updated_by_user` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改用户',
  `last_update_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `object_version_number` bigint NULL DEFAULT 1 COMMENT '版本号',
  `request_id` bigint NULL DEFAULT NULL COMMENT '请求id',
  `program_id` bigint NULL DEFAULT NULL COMMENT '程序id',
  `last_update_login` bigint NULL DEFAULT NULL COMMENT '最后登陆人',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ldf_idx_uk_form_code`(`form_code` ASC) USING BTREE,
  INDEX `ldf_idx_process_code`(`process_code` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'LCP 动态表单' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for lcp_dynamic_form_detail
-- ----------------------------
DROP TABLE IF EXISTS `lcp_dynamic_form_detail`;
