  `required` tinyint(1) NULL DEFAULT NULL COMMENT '是否必填：0否/1是',
  `data_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '下拉框类型：数据字典编码',
  `lov_code` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'LOV编码',
  `date_format` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '日期类型',
  `multi_choice` tinyint(1) NULL DEFAULT NULL COMMENT '是否多选，默认0：0否/1是',
  `begin_date` datetime NULL DEFAULT NULL COMMENT '字段类型为日期时，设置的最小可选日期时间',
  `end_date` datetime NULL DEFAULT NULL COMMENT '字段类型为日期时，设置的最大可选日期时间',
  `rule_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '流水号规则代码',
  `sort_num` int NULL DEFAULT NULL COMMENT '排序号',
  `created_by` bigint NULL DEFAULT NULL COMMENT '创建人',
  `created_by_user` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '创建用户',
  `creation_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `last_updated_by` bigint NULL DEFAULT NULL COMMENT '修改人',
  `last_updated_by_user` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改用户',
  `last_update_date` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `object_version_number` bigint NULL DEFAULT 1 COMMENT '版本号',
  `request_id` bigint NULL DEFAULT NULL COMMENT '请求id',
  `program_id` bigint NULL DEFAULT NULL COMMENT '程序id',
  `last_update_login` bigint NULL DEFAULT NULL COMMENT '最后登陆人',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `ldfd_idx_form_id`(`form_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

