-- ----------------------------
-- Table structure for smp_inspection_ledger
-- ----------------------------
DROP TABLE IF EXISTS `smp_inspection_ledger`;
CREATE TABLE `smp_inspection_ledger`  (
  `id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `project_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '项目id',
  `project_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '项目名称',
  `inspection_time` datetime NULL DEFAULT NULL COMMENT '检查日期',
  `leader` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查组长',
  `personnel` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查人员',
  `inspection_level` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查层级(字典：smp_inspection_level)',
  `evaluate_time` datetime NULL DEFAULT NULL COMMENT '评价时间（提交时间）',
  `total_score` double NULL DEFAULT NULL COMMENT '总评价得分',
  `inspection_results` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '检查结果（字典：smp_inspection_results）',
